const stepMs = {}; const R = {};
const t = async (k, f) => { const s = Date.now(); try { return await f(); } catch (e) { print(`${k} ERROR: ${e?.name}: ${e?.message}`); R[k+"Error"] = String(e?.message ?? e); } finally { stepMs[k] = Date.now() - s; } };
await t("s1", async () => { print(JSON.stringify(await computer.capabilities())); print(JSON.stringify(await computer.displays())); });
await t("s2", async () => { await computer.display("all"); const shot = await computer.screenshot({ silent: true }); print(shot.width, shot.height, shot.path); });
const win = await t("s3", async () => { const w = await computer.window({ title: "DM-1041 fixture A" }); print(w.id, JSON.stringify(w.bounds), w.focused); return w; });
let nodeCount, buttonFound, inputFound, btn, clickPoint, screenshotSize;
await t("s4", async () => { const tree = await win.ax(); nodeCount = tree.split("\n").filter(l => l.includes("[ref=")).length; buttonFound = /button "Probe button"/i.test(tree); inputFound = tree.split("\n").some(l => l.includes('"Probe input"')); print(nodeCount, buttonFound, inputFound); });
await t("s5", async () => { [btn] = await win.find({ role: "button", title: "Probe button" }); await btn.press(); });
await t("s6", async () => { const [field] = await win.find({ title: "Probe input" }); await field.type("hello"); });
await t("s7", async () => {
  const shot = await win.screenshot({ silent: true }); screenshotSize = { width: shot.width, height: shot.height };
  const b = await btn.bounds(); const wb = win.bounds;
  const sx = shot.width / wb.width, sy = shot.height / wb.height;
  const x = Math.round((b.x + b.width / 2 - wb.x) * sx), y = Math.round((b.y + b.height / 2 - wb.y) * sy);
  const inside = x >= 0 && y >= 0 && x < shot.width && y < shot.height;
  clickPoint = { x, y, inside, btnBounds: b, scale: [sx, sy] };
  if (!inside) throw new Error("click point outside screenshot");
  await win.click(x, y);
});
await t("s8", async () => { await win.press("escape"); });
print("PROBE_RESULT " + JSON.stringify({ stepMs, nodeCount, buttonFound, inputFound, clickPoint, windowBounds: win?.bounds, screenshotSize }));

